def backfill_payment_amounts(apps, schema_editor):
    Transaction = apps.get_model('api', 'Transaction')
    transactions = Transaction.objects.filter(
    ).select_related('listing')
    for transaction in transactions.iterator():
        updates = {}
        if transaction.status == 'Completed':
            if transaction.amount_ngn is None:
                updates['amount_ngn'] = transaction.listing.price_ngn
            if transaction.completed_at is None:
                updates['completed_at'] = transaction.updated_at or transaction.created_at
        if transaction.paid_at is not None and not transaction.payment_ref:
            updates['payment_ref'] = f'LEGACY-{transaction.pk}'
        if updates:
            updates.setdefault('currency', 'NGN')
            Transaction.objects.filter(pk=transaction.pk).update(**updates)


def validate_single_active_deal(apps, schema_editor):
    Transaction = apps.get_model('api', 'Transaction')
    duplicate_listing_ids = list(
        Transaction.objects.filter(status__in=['Reserved', 'Completed'])
        .values('listing_id')
        .annotate(total=models.Count('id'))
        .filter(total__gt=1)
        .values_list('listing_id', flat=True)[:20]
    )
    if duplicate_listing_ids:
        raise RuntimeError(
            'Cannot add one_active_deal_per_listing; multiple Reserved/Completed '
            f'transactions exist for listing IDs: {duplicate_listing_ids}. '
            'Resolve the conflicting deals without deleting transaction history, then retry.'
        )


